export interface Reading { cpu: number; memory: number; gpu: number; }

export function clampReading(value: number): number {
  return Math.max(0, Math.min(100, value));
}

export function restorePanels(regions: string[], panels: { region: string }[]) {
  const ready = new Set(regions);
  return panels.filter((panel) => ready.has(panel.region));
}

import { expect, test } from 'vitest';
import { restorePanels } from '../src/restore';

test('waits for the target region', () => {
  expect(restorePanels([], [{ region: 'side' }])).toEqual([]);
});
